tests:
assert string_indices(["apple", "orange", "apple", "banana"]) == {"apple": [0, 2], "orange": [1], "banana": [3]}

assert string_indices(["banana", "banana", "banana"]) == {"banana": [0, 1, 2]}

assert string_indices([]) == {}

assert string_indices(["kiwi"]) == {"kiwi": [0]}

assert string_indices(["pear", "peach", "plum", "pear", "plum"]) == {"pear": [0, 3], "peach": [1], "plum": [2, 4]}

assert string_indices(["grape", "melon", "grape", "melon", "grape"]) == {"grape": [0, 2, 4], "melon": [1, 3]}

assert string_indices(["strawberry", "blueberry", "strawberry", "blueberry", "strawberry", "blueberry"]) == {"strawberry": [0, 2, 4], "blueberry": [1, 3, 5]}

assert string_indices(["cherry", "cherry", "cherry", "cherry"]) == {"cherry": [0, 1, 2, 3]}

assert string_indices(["mango", "kiwi", "mango", "kiwi", "mango", "kiwi"]) == {"mango": [0, 2, 4], "kiwi": [1, 3, 5]}

assert string_indices(["watermelon", "pineapple", "watermelon", "pineapple", "watermelon", "pineapple", "watermelon"]) == {"watermelon": [0, 2, 4, 6], "pineapple": [1, 3, 5]}
